declare_lint ! { #[doc = " The `improper_ctypes` lint detects incorrect use of types in foreign"] #[doc = " modules."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " unsafe extern \"C\" {"] #[doc = "     static STATIC: String;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " The compiler has several checks to verify that types used in `extern`"] #[doc = " blocks are safe and follow certain rules to ensure proper"] #[doc = " compatibility with the foreign interfaces. This lint is issued when it"] #[doc = " detects a probable mistake in a definition. The lint usually should"] #[doc = " provide a description of the issue, along with possibly a hint on how"] #[doc = " to resolve it."] IMPROPER_CTYPES , Warn , "proper use of libc types in foreign modules" }